<?php
namespace App\Http\Controllers;
use App\Models\Customer; use Illuminate\Http\Request;
class CustomerController extends Controller { public function index(){return view('customers.index',['customers'=>Customer::paginate(5)]);} public function create(){return view('customers.form',['customer'=>new Customer]);} public function store(Request $r){Customer::create($this->valid($r));return redirect()->route('clientes.index')->with('success','Cliente cadastrado com sucesso.');} public function edit(Customer $cliente){return view('customers.form',['customer'=>$cliente]);} public function update(Request $r,Customer $cliente){$cliente->update($this->valid($r));return redirect()->route('clientes.index')->with('success','Cliente atualizado.');} public function destroy(Customer $cliente){$cliente->delete();return back()->with('success','Cliente excluído.');} private function valid(Request $r){return $r->validate(['name'=>'required','email'=>'nullable|email','phone'=>'required','address'=>'required']);}}
